[Windows.Forms.Application]::EnableVisualStyles();$a=[Reflection.Assembly]::LoadFrom((Join-Path $PWD 'DeepSeekBalance\build\DeepSeekBalance.exe'));$t=$a.GetType('DeepSeekBalance.BalancePanel');$flags=[Reflection.BindingFlags]'Instance,NonPublic';$p=[Activator]::CreateInstance($t,[object[]]@([Action]{},[Action]{}));$show=$t.GetMethod('ShowAnimated');$hide=$t.GetMethod('HideAnimated');$origin=[Drawing.Point]::new(900,900);$p.Location=[Drawing.Point]::new(715,478)
