 $hide.Invoke($p,[object[]]@($origin)) | Out-Null;Pump 250;$m=$t.GetField('appearance',$flags).GetValue($p);$m.GetType().GetField('Transparency').SetValue($m,[double]100);$show.Invoke($p,[object[]]@($origin)) | Out-Null;Pump 350;Check 'Animation preserves fully transparent background' ($p.Visible -and $p.TransparencyKey.ToArgb() -eq [Drawing.Color]::Black.ToArgb());$hide.Invoke($p,[object[]]@($origin)) | Out-Null;Pump 250;Check 'Fully transparent panel also closes cleanly' ((SurfaceCount) -eq 0 -and -not $p.Visible)
